CREATE TABLE IF NOT EXISTS gateway_documents (owner_id TEXT NOT NULL, doc_id TEXT NOT NULL, tenant_id TEXT NOT NULL, doc_type TEXT NOT NULL, service_id TEXT NOT NULL, session_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('creating', 'ready', 'failed')), version INTEGER, error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (owner_id, doc_id), UNIQUE (owner_id, idempotency_key));
CREATE INDEX IF NOT EXISTS gateway_documents_list_idx ON gateway_documents(owner_id, doc_type, state, updated_at DESC);
INSERT OR IGNORE INTO gateway_documents (owner_id, doc_id, tenant_id, doc_type, service_id, session_id, idempotency_key, state, version, error, created_at, updated_at) SELECT docs.owner_id, docs.doc_id, docs.owner_id, docs.doc_type, docs.doc_type, docs.owner_id || ':' || docs.doc_id, 'legacy:' || docs.doc_type || ':' || docs.doc_id, 'ready', COALESCE((SELECT MAX(snapshots.version) FROM snapshots WHERE snapshots.doc_type = docs.doc_type AND snapshots.doc_id = docs.doc_id), 1), NULL, docs.created_at, docs.updated_at FROM docs;